import{_ as a,o,c as e,a6 as r}from"./chunks/framework.QBF2cGGQ.js";const q=JSON.parse('{"title":"13 · 路径与项目","description":"","frontmatter":{},"headers":[],"relativePath":"guide/13-path.md","filePath":"guide/13-path.md","lastUpdated":1793327470000}'),l={name:"guide/13-path.md"};function i(n,t,s,u,d,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="_13-·-路径与项目" tabindex="-1">13 · 路径与项目 <a class="header-anchor" href="#_13-·-路径与项目" aria-label="Permalink to &quot;13 · 路径与项目&quot;">​</a></h1><blockquote><p>知识清单不等于学习计划。这一层给顺序和验收标准——每个阶段都有&quot;做出来什么&quot;，而不是&quot;学了什么&quot;。</p></blockquote><h2 id="为什么要有验收标准" tabindex="-1">为什么要有验收标准 <a class="header-anchor" href="#为什么要有验收标准" aria-label="Permalink to &quot;为什么要有验收标准&quot;">​</a></h2><p>&quot;学完 RAG&quot;这句话没有意义，因为永远学不完。有意义的是&quot;我做出了一个 Recall@5 达到 80% 的知识库，并且能说清每个错误是检索问题还是生成问题&quot;。</p><p><strong>验收标准的作用是把&quot;感觉学会了&quot;变成&quot;可以被别人检验&quot;。</strong> 它同时也是你面试时唯一能讲的东西——面试官不关心你看了什么教程，只关心你做出来的东西有什么数字。</p><h2 id="五个阶段" tabindex="-1">五个阶段 <a class="header-anchor" href="#五个阶段" aria-label="Permalink to &quot;五个阶段&quot;">​</a></h2><h3 id="阶段-0-2-周-跑通与认知" tabindex="-1">阶段 0（2 周）：跑通与认知 <a class="header-anchor" href="#阶段-0-2-周-跑通与认知" aria-label="Permalink to &quot;阶段 0（2 周）：跑通与认知&quot;">​</a></h3><ul><li>读完本图第 00~02 层</li><li>用官方 SDK 裸调三家厂商的 API（不要用框架）</li><li>写一个流式聊天页面，支持中断与重新生成</li></ul><p><strong>验收</strong>：能解释 token 计费怎么算、temperature 调高会发生什么、为什么流式输出是单向的。</p><h3 id="阶段-1-4-6-周-rag-端到端" tabindex="-1">阶段 1（4~6 周）：RAG 端到端 <a class="header-anchor" href="#阶段-1-4-6-周-rag-端到端" aria-label="Permalink to &quot;阶段 1（4~6 周）：RAG 端到端&quot;">​</a></h3><ul><li>做一个能上传文档、能溯源引用、有 50 条评测集的知识库</li><li>至少实现混合检索 + 重排</li><li>记录每次检索的完整 trace</li></ul><p><strong>验收</strong>：Recall@5 ≥ 80%，且拿到一个错误案例时，能判断是&quot;没检索到&quot;还是&quot;检索到但没用&quot;。</p><h3 id="阶段-2-4-周-agent-与工具" tabindex="-1">阶段 2（4 周）：Agent 与工具 <a class="header-anchor" href="#阶段-2-4-周-agent-与工具" aria-label="Permalink to &quot;阶段 2（4 周）：Agent 与工具&quot;">​</a></h3><ul><li>写 3 个工具 + ReAct 循环 + 人工审批点 + 成本上限</li><li>加终止条件（最大步数 / 最大成本 / 无进展检测）</li><li>每一步都能回放</li></ul><p><strong>验收</strong>：10 步任务成功率 ≥ 70%，且有完整 trace 可回放；故意制造工具失败，系统能自愈或优雅退出。</p><h3 id="阶段-3-3-周-评测与可观测" tabindex="-1">阶段 3（3 周）：评测与可观测 <a class="header-anchor" href="#阶段-3-3-周-评测与可观测" aria-label="Permalink to &quot;阶段 3（3 周）：评测与可观测&quot;">​</a></h3><ul><li>接入 Langfuse（或同类）</li><li>把评测跑进 CI，prompt 改动自动回归</li><li>建立 badcase 归因流程</li></ul><p><strong>验收</strong>：一次 prompt 改动能给出&quot;变好/变坏&quot;的量化结论，而不是&quot;我感觉好点了&quot;。</p><h3 id="阶段-4-按需-微调与部署" tabindex="-1">阶段 4（按需）：微调与部署 <a class="header-anchor" href="#阶段-4-按需-微调与部署" aria-label="Permalink to &quot;阶段 4（按需）：微调与部署&quot;">​</a></h3><ul><li>LoRA 微调一个小模型</li><li>vLLM 部署 + 量化对比</li><li>算出&quot;自部署 vs 调 API&quot;的成本交叉点</li></ul><p><strong>验收</strong>：能给出一个有数字的结论：&quot;在我们的 QPS 下，自建在每月 X 次请求以上才划算&quot;。</p><h2 id="四个能写进简历的项目" tabindex="-1">四个能写进简历的项目 <a class="header-anchor" href="#四个能写进简历的项目" aria-label="Permalink to &quot;四个能写进简历的项目&quot;">​</a></h2><h3 id="_1-带评测的企业知识库" tabindex="-1">1. 带评测的企业知识库 <a class="header-anchor" href="#_1-带评测的企业知识库" aria-label="Permalink to &quot;1. 带评测的企业知识库&quot;">​</a></h3><p>亮点不是&quot;用了 RAG&quot;，而是&quot;有 200 条评测集、Recall 从 62% 提到 89%、成本降 40%&quot;。<strong>数字是唯一有说服力的东西。</strong></p><p>要能讲清三件事：为什么选这个分块策略（有对比实验）、为什么加重排（有前后指标）、权限隔离怎么做的（有越权测试）。</p><h3 id="_2-多工具-agent-人工审批" tabindex="-1">2. 多工具 Agent + 人工审批 <a class="header-anchor" href="#_2-多工具-agent-人工审批" aria-label="Permalink to &quot;2. 多工具 Agent + 人工审批&quot;">​</a></h3><p>亮点是可靠性设计：终止条件、幂等、审批点、trace 回放。讲的时候重点放在&quot;我怎么让它不出事&quot;，而不是&quot;它能做多少事&quot;。</p><h3 id="_3-模型网关-成本看板" tabindex="-1">3. 模型网关 + 成本看板 <a class="header-anchor" href="#_3-模型网关-成本看板" aria-label="Permalink to &quot;3. 模型网关 + 成本看板&quot;">​</a></h3><p>亮点是工程性：多模型路由、降级、限流、按租户成本分摊。这个项目最像真实生产系统，也最能体现你从&quot;做功能&quot;到&quot;做平台&quot;的跨越。</p><h3 id="_4-给开源项目提-pr" tabindex="-1">4. 给开源项目提 PR <a class="header-anchor" href="#_4-给开源项目提-pr" aria-label="Permalink to &quot;4. 给开源项目提 PR&quot;">​</a></h3><p>LangChain / LlamaIndex / Langfuse 的 issue 区里挑真实 bug。这是最快的背书——它证明你能读懂别人的大型代码库。</p><h2 id="时间分配建议" tabindex="-1">时间分配建议 <a class="header-anchor" href="#时间分配建议" aria-label="Permalink to &quot;时间分配建议&quot;">​</a></h2><p>如果你每周能投入 10 小时，大概是这样：</p><table tabindex="0"><thead><tr><th>阶段</th><th>周数</th><th>累计</th></tr></thead><tbody><tr><td>0 跑通</td><td>2</td><td>2</td></tr><tr><td>1 RAG</td><td>5</td><td>7</td></tr><tr><td>2 Agent</td><td>4</td><td>11</td></tr><tr><td>3 评测与可观测</td><td>3</td><td>14</td></tr><tr><td>4 微调与部署</td><td>3</td><td>17</td></tr></tbody></table><p><strong>这是经验估算，不是承诺。</strong> 实际耗时高度取决于你每天能投入多少、以及第一个项目遇到的文档解析有多脏。做好&quot;RAG 阶段超时&quot;的心理准备——这是最常见的。</p><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h2><ul><li><strong>必读文档</strong> <span class="prio prio-must">必须</span> — OpenAI / Anthropic / Qwen 的官方 prompting 与 tool use 文档，比任何二手教程准。</li><li><strong>必读文章</strong> <span class="prio prio-must">必须</span> — Anthropic《Building Effective Agents》——关于&quot;为什么优先用工作流&quot;的最佳论述。</li><li><strong>MCP 规范</strong> <span class="prio prio-must">必须</span> — modelcontextprotocol.io 的规范与示例，一小时能读完。</li><li><strong>开源项目精读</strong> <span class="prio prio-imp">重要</span> — 选一个 RAG 框架读它的检索链路源码，比看十篇博客有用。</li><li><strong>论文</strong> <span class="prio prio-imp">重要</span> — 只挑必要的：Attention Is All You Need、RAG 原论文、LoRA、DPO、ReAct。</li><li><strong>社区</strong> <span class="prio prio-opt">选学</span> — LangChain / LlamaIndex Discord、HuggingFace 论坛、以及国内的 AI 工程实践群。</li></ul><h2 id="最后一句" tabindex="-1">最后一句 <a class="header-anchor" href="#最后一句" aria-label="Permalink to &quot;最后一句&quot;">​</a></h2><p>这份清单有 400 多条，别指望按顺序全做完。<strong>正确用法是：先按阶段走主干，遇到具体问题再回来查。</strong></p><p>真正决定你能不能转成的，不是覆盖了多少条，而是你有没有一个&quot;能拿出数字&quot;的项目。清单是地图，项目是路。</p>',40)])])}const c=a(l,[["render",i]]);export{q as __pageData,c as default};
